const STATUS:any={draft:'Draft',awaiting_review:'Waiting for review',changes_requested:'Needs changes',approved:'Approved',rejected:'Declined',scheduled:'Scheduled',published:'Live',archived:'Archived',active:'On',not_configured:'Not set up',not_connected:'Not connected',queued:'Queued',running:'Working',completed:'Done',failed:'Failed',blocked:'Waiting for connection',rendering:'Making it',disabled:'Off',recorded:'Saved',idea:'Idea',all:'All',copy:'Writing',image:'Images',carousel:'Carousels',video:'Videos',audio:'Audio',files:'Files'};
