const LABEL:any={overview:'Home','01-onboard':'Client & brand','02-strategy':'Strategy','03-plan':'Calendar & budget','04-hooks':'Ideas','05-content':'Writing','06-design-video':'Design & video','07-approve':'Review','08-publish':'Posting','09-results':'Results',seo:'Google search',geo:'AI answers',ads:'Ads',influencers:'Creators',managing:'Team',library:'Files',settings:'Settings'};
const ABOUT:any={'01-onboard':'Who the client is, and how their brand looks and sounds.','02-strategy':'The big direction: who we talk to, what we say and where.','03-plan':'What goes out when, and how the money is split.','04-hooks':'Opening lines that make people stop scrolling. Pick the best one.','05-content':'Scripts, captions and calls to action, checked before review.','06-design-video':'Turn written content into posts, carousels and reels in the client’s brand.','07-approve':'Check work before it goes out. Nothing is posted or spent without a yes here.','08-publish':'When and where approved content goes live.','09-results':'What actually happened, in real numbers, and what we learned.',seo:'Help the client show up on Google Search and Google Maps.',geo:'Help the client get mentioned in ChatGPT, Gemini and Google’s AI answers.',ads:'Plan ad spend. Every launch, pause or budget change needs a yes first.',influencers:'Find and brief creators. Paid posts must be clearly labelled.',managing:'Tasks, owners, deadlines and invoices.',library:'Every file, post and video in one place.',settings:'People, access and how the workspace runs.'};
