{page==='07-approve'&&<><div className="section-title"><div className="tab-row">{['awaiting_review','approved','changes_requested','rejected'].map(s=><button key={s} onClick={()=>setFilter(s)} className={(filter==='all'?'awaiting_review':filter)===s?'selected':''}>{badge(s)} <span>{byKind('Approval').filter((r:any)=>r.status===s).length}</span></button>)}</div></div><div className="approval-list">{byKind('Approval').filter((r:any)=>r.status===(filter==='all'?'awaiting_review':filter)).map((r:any)=><article className="approval-card" key={r.id}><div className="approval-icon"><CheckCheck size={24}/></div><div className="approval-copy"><div className="tag-row"><span className="eyebrow">{KIND[r.data.target_kind]||r.data.target_kind} · version {r.data.target_version}</span><Status value={r.status}/></div><h3>{r.title}</h3><p>{r.data.action}</p><small>{r.data.reversible?'Can be changed later with a new version':'Goes outside EXORA — check exactly what will happen'}</small>{r.data.reason&&<p className="review-reason">{r.data.approver_name}: {r.data.reason}</p>}</div><button className="button primary" onClick={()=>setModal({type:'review',record:r})}>{r.status==='awaiting_review'&&canReview?'Review':'See review'}<ArrowUpRight size={15}/></button></article>)}</div>{!byKind('Approval').filter((r:any)=>r.status===(filter==='all'?'awaiting_review':filter)).length&&<Empty title="Nothing to review">Work sent for review shows up here.</Empty>}</>}
